alter table work_goals add column checkpoint_pinned boolean not null default false;
alter table memory_suggestions add column work_goal_id uuid references work_goals(id) on delete cascade;
alter table memory_suggestions add column work_goal_revision integer;
alter table memories add column work_goal_id uuid references work_goals(id) on delete cascade;
alter table memories add column work_goal_revision integer;
-- One reviewed proposal per goal. A forgotten lesson cannot be silently
-- regenerated by replaying the same model tool on the same completed goal.
create unique index memory_suggestions_work_goal on memory_suggestions(owner_user_id,work_goal_id)
  where work_goal_id is not null;
